\label{app:fixed}
Let $\delta>0$, $\beta\geq6$, $0<c\leq r_0\leq C$, with $r_0$ smooth
on a neighborhood of $\overline\Omega$, and let
$v_0\in C_c^\infty(\Omega;\mathbb R^2)$. There is a global solution
$(r,v)$ of
\begin{equation}\label{app:fixedsystem}
 \partial_t r+\operatorname{div}(rv)=0,\qquad
 \partial_t(rv)+\operatorname{div}(rv\otimes v)+\nabla p_\delta(r)
       =\operatorname{div}\mathbb S(v),\qquad v|_{\partial\Omega}=0,
\end{equation}
with the prescribed density and momentum initial terms $r_0$ and $r_0v_0$.
For every $T<\infty$,
\begin{gather*}
 r\in L^\infty(0,T;L^\beta(\Omega))\cap L^{\beta+1}(Q_T)
          \cap C_{\mathrm{weak}}([0,T];L^\beta(\Omega)),\qquad r\geq0,\\
 v\in L^2(0,T;W^{1,2}_0(\Omega;\mathbb R^2)),\qquad
 \sqrt r\,v\in L^\infty(0,T;L^2(\Omega;\mathbb R^2)),\\
 rv\in C_{\mathrm{weak}}([0,T];L^{2\beta/(\beta+1)}(\Omega;\mathbb R^2)).
\end{gather*}
For every $b\in C^1([0,\infty))$ whose derivative is compactly
supported, continuity is renormalized:
\begin{equation}\label{app:fixed-renormalized}
 \partial_t b(r)+\operatorname{div}(b(r)v)
 +(rb'(r)-b(r))\operatorname{div}v=0,
\end{equation}
with initial term $b(r_0)$. The same identity also holds for
\begin{equation}\label{app:PWclass}
 b\in C^2([0,\infty)),\qquad
 |b(r)|+|rb'(r)|+|r^2b''(r)|\leq C_b(1+r^2).
\end{equation}
For almost every $t>0$,
\begin{equation}\label{app:fixedenergy}
 E_\delta(t)+\int_0^t\!\int_\Omega\mathbb S(v):\nabla v\,dx\,ds
 \leq E_\delta(0),\qquad
 E_\delta(t)=\int_\Omega\left(\frac12r|v|^2+H_\delta(r)\right)(t)dx.
\end{equation}

\label{app:PW}
Let $\zeta\in C_c^\infty(\Omega)$ be nonnegative and
$0<\alpha<1/6$. The selected solutions satisfy
\begin{align}
 \sup_{\omega\in\mathbb S^1}\int_0^T\!\int_{\mathbb R}
 \left(\int_{\{\omega\cdot x=\tau\}}\zeta(x)\rho_n(t,x)\,d\ell\right)^2
 d\tau\,dt&\leq C_{\zeta,T},\label{app:Radon}\\
 \|\zeta\rho_n\|_{L^2(0,T;H^{-1/2}(\mathbb R^2))}
 &\leq C_{\zeta,T},\label{app:halfderivative}\\
 \int_{Q_T}\zeta^2\bigl(\rho_n+\delta_n\rho_n^\beta\bigr)
                         \rho_n^\alpha\,dx\,dt
 &\leq C_{\zeta,\alpha,T}.\label{app:localgain}
\end{align}
The zero extension is used in \eqref{app:Radon}--\eqref{app:halfderivative}.
The constants depend only on the uniform initial augmented energy,
mass, $T$, $\Omega$, $\mu$, $\lambda$, the fixed $\beta$, and the displayed
localization and exponent. They require no common bound on
$\|\rho_{0,n}\|_\infty$, $(\inf\rho_{0,n})^{-1}$, or
$\|u_{0,n}\|_{W^{1,2}}$.

\label{mom:exponents}
For every $D\Subset\Omega$,
\begin{equation}\label{mom:mixed}
 \begin{aligned}
  \rho_n&\text{ is bounded in }L^4(0,T;L^{32/31}(D)),\\
  m_n&\text{ is bounded in }L^3(0,T;L^{96/95}(D)),\\
  F_n&\text{ is bounded in }L^{6/5}(0,T;L^{192/191}(D)).
 \end{aligned}
\end{equation}

Since $p_n\ge\rho_n$, \eqref{app:localgain} gives a uniform
$L^{9/8}(Q_D)$ bound. Interpolation with mass yields
\[
 \|\rho_n\|_{L^4_tL^{32/31}_x(D)}
 \le\|\rho_n\|_{L^\infty_tL^1_x(D)}^{23/32}
      \|\rho_n\|_{L^{9/8}(Q_D)}^{9/32}\le C_D.
\]
Using kinetic energy and the planar embedding
$W^{1,2}_0(\Omega)\hookrightarrow L^q(\Omega)$ for every finite $q$,
H\"older's inequality gives
\begin{align*}
 \|m_n\|_{L^3_tL^{96/95}_x(D)}
 &\le\|\rho_n\|_{L^4_tL^{32/31}_x(D)}^{2/3}
       \|\rho_n|u_n|^2\|_{L^\infty_tL^1_x(D)}^{1/3}
       \|u_n\|_{L^2_tL^{32}_x(D)}^{1/3}\le C_D,\\
 \|F_n\|_{L^{6/5}_tL^{192/191}_x(D)}
 &\le\|m_n\|_{L^3_tL^{96/95}_x(D)}
       \|u_n\|_{L^2_tL^{192}_x(D)}\le C_D.
\end{align*}

\label{mom:compact}
For each $\chi\in C_c^\infty(\Omega)$ and each smooth ball $B$ containing
its support, with the localized functions extended by zero, a subsequence
satisfies
\begin{align}
 \chi\rho_n&\longrightarrow\chi\rho
       &&\text{strongly in }L^2(0,T;H^{-1}(B)),\label{mom:rho-compact}\\
 \chi m_n&\longrightarrow\chi m
       &&\text{strongly in }L^2(0,T;W^{-1,192/95}(B)).\label{mom:exact}
\end{align}
In particular localized momentum converges strongly in $L^2_tH^{-1}_x$.

\label{mom:identification}
The weak limits satisfy $m=\rho u$ almost everywhere, and for every
$D\Subset\Omega$,
\begin{equation}\label{mom:convection}
 F_n\rightharpoonup\rho u\otimes u
       \quad\text{in }L^{6/5}(0,T;L^{192/191}(D)).
\end{equation}

\label{mom:artificial}
For every $D\Subset\Omega$,
\begin{equation}\label{mom:AP}
 \delta_n\rho_n^\beta\longrightarrow0
       \quad\text{strongly in }L^1(Q_D).
\end{equation}

\label{flux:proposition}
For every fixed integer $k\ge1$, let $t_k,P_k,h_k$ be the limits in
\eqref{flux:weak-caps}. Then, with $\nu=2\mu+\lambda>0$,
\begin{equation}\label{flux:identity}
 P_k-\rho t_k
   =\nu\bigl(h_k-t_k\operatorname{div}u\bigr)
       \qquad\text{almost everywhere in }Q,
\end{equation}
and every term belongs to $L^1(Q)$.

\label{var:abstract}
Let $X\ge0$ with $\mathbb E X=r<\infty$,  and  $T_k$ be the truncations of
Section~\ref{sec:flux}. Let
\[
 t_k=\mathbb E T_k(X),\qquad C_k=\operatorname{Cov}(X,T_k(X)),\qquad
 V_k=\operatorname{Var}(T_k(X)),\qquad V=\mathbb E|X-r|^2\in[0,\infty].
\]
Then
\begin{equation}\label{var:monotone}
 0\le V_k\le C_k,\qquad C_k\uparrow V\quad(k\to\infty).
\end{equation}
If $V<\infty$, then
\begin{equation}\label{var:jensen}
 0\le T_k(r)-t_k,\qquad |T_k(r)-t_k|^2\le V.
\end{equation}

\label{var:bound}
Let $d_n=\operatorname{div}u_n$, $d=\operatorname{div}u$, and
$D_*:=\sup_n\int_{Q_T}|d_n|^2$. Then
\begin{equation}\label{var:global}
 \int_{Q_T}V\le\nu^2D_*,\qquad \nu=2\mu+\lambda.
\end{equation}
More precisely, for every fixed $k$,
\begin{equation}\label{var:estimate}
 \int_{Q_T}C_k
 \le\nu D_*^{1/2}\left(\int_{Q_T}V_k\right)^{1/2}.
\end{equation}

\label{var:residual}
For every integer $k>2M$,
\begin{equation}\label{var:residual-majorant}
 \mathbf1_{A_{k,M}}\mathbb E|a_k(X)|^2\le4V_k\le4V
 \qquad\text{almost everywhere in }Q_T.
\end{equation}
Moreover,
\begin{equation}\label{var:residual-limit}
 \int_{A_{k,M}}\mathbb E|a_k(X)|^2\longrightarrow0
 \qquad\text{as }k\to\infty.
\end{equation}

\label{var:discrepancy}
With $e_k:=T_k(\rho)-t_k$,
\begin{equation}\label{var:discrepancy-limit}
 0\le e_k,\qquad e_k\longrightarrow0
                 \quad\text{strongly in }L^2(Q_T).
\end{equation}
Also $t_k\uparrow\rho$ almost everywhere and in $L^1(Q_T)$.

\label{close:globalcap}
The zero extensions of $t_K,u,S_K$ satisfy
\begin{equation}\label{close:capequation}
 \partial_t t_K+\operatorname{div}(t_Ku)=-S_K,
 \qquad t_K|_{t=0}=T_K(\rho_0).
\end{equation}
For every smooth scalar test $\psi$ up to the spatial boundary,
vanishing near $t=T$,
\begin{equation}\label{close:capweak}
 \int_Q(t_K\partial_t\psi+t_Ku\cdot\nabla\psi-S_K\psi)
 +\int_\Omega T_K(\rho_0)\psi(0)=0.
\end{equation}
On any ball containing $\overline\Omega$, the zero-extended caps
$q_{K,n}:=T_K(\rho_n)$ converge to $t_K$ in $C([0,T];H^{-1})$.

\label{close:renormalization}
For every $b\in C^1([0,\infty))$ with compactly supported derivative,
\begin{equation}\label{close:renormrho}
 \partial_tb(\rho)+\operatorname{div}(b(\rho)u)
 +(\rho b'(\rho)-b(\rho))\operatorname{div}u=0
\end{equation}
globally, with initial value $b(\rho_0)$. For the tests of
Lemma~\ref{close:globalcap},
\begin{align}\label{close:renormweak}
 &\int_Q[b(\rho)\partial_t\psi+b(\rho)u\cdot\nabla\psi
       -(\rho b'(\rho)-b(\rho))\operatorname{div}u\,\psi]
       \notag\\
 &\hspace{35mm}+\int_\Omega b(\rho_0)\psi(0)=0.
\end{align}

\label{close:strongdensity}
Along the common subsequence,
\begin{equation}\label{close:strongLone}
 \rho_n\longrightarrow\rho\qquad\text{strongly in }L^1(Q).
\end{equation}
